const listAuditActors = `-- name: ListAuditActors :many
SELECT DISTINCT actor_name FROM audit_logs
WHERE actor_name IS NOT NULL AND actor_name <> ''
ORDER BY actor_name ASC
`

func (q *Queries) ListAuditActors(ctx context.Context) ([]sql.NullString, error) {
	rows, err := q.db.QueryContext(ctx, listAuditActors)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []sql.NullString{}
	for rows.Next() {
		var actor_name sql.NullString
		if err := rows.Scan(&actor_name); err != nil {
			return nil, err
		}
		items = append(items, actor_name)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

